-- Behavioral families share parameters, never emitter coordinates or artwork.
local families={cave_ice='ice',forest='canopy',tall_grass='canopy',plain='open',desert='desert',beach='shore',mountain='rock',rocky='rock',pond='water',water='water',wallace='water',interior='window',cave='cave',lavender='lavender',ghost='spectral',ice='ice',virtual='virtual',blue='hall',bruno='hall',building='hall',dragon='hall',grand_hall='hall',gym='hall',rocket='hall',sidney='hall'}
local styles={canopy=1,open=2,desert=3,shore=4,rock=5,water=6,window=7,cave=8,lavender=9,spectral=10,ice=11,virtual=12,hall=13}
local reflections={pond={.04,.29,.92,.20},water={0,.43,1,.57},wallace={0,.35,1,.65}}
local S={scenes=scenes,families=families,styles=styles}
function S.effect(id,profile)
 local s=scenes[id];local family=families[id]
 if not s or not family then return nil end
 local solar=family=='canopy' or family=='open' or family=='desert' or family=='shore' or family=='rock' or family=='window' or family=='water' and id~='wallace'
 local color
 if not solar then color=id=='lavender' and {.78,.50,1} or s.color end
 return {family=family,style=styles[family],solar=solar,color=color,reflection=reflections[id] or {0,0,0,0},lights=id=='lavender' and {{.10,.43,.16,.22}} or id=='tall_grass' and {{.31,.015,.13,.18},{.56,.025,.13,.16}} or nil}
end
local sunlight={predawn=.10,dawn=.55,morning=.90,noon=1,dusk=.55,night=.16}
function S.resolve(id,profile)
 local s=scenes[id];if not s then return {mode=0,color={1,1,1},amplitude=0,daylight=0,lights={},protected={}} end
 return {mode=s.mode,color=s.color,amplitude=s.amplitude,daylight=sunlight[profile] or 1,lights=s.lights,protected=s.protected}
end
-- Pure affine mapping, shared by background, arenas and future detail images.
function S.arenaTransform(iw,ih,shape,cx,cy,width,bgx,bgw,bgh,bgy)
 local k=width/(shape.r-shape.l)
 return {iw*k/bgw,ih*k/bgh,(cx-shape.cx*k-bgx)/bgw,(cy-shape.cy*k-(bgy or 0))/bgh}
end
function S.point(transform,u,v) return u*transform[1]+transform[3],v*transform[2]+transform[4] end
return S
